// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Rule One: Mock wisely
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCart = {
  items: [
    { id: '1', name: 'Widget', price: 29.99 },
    { id: '2', name: 'Gadget', price: 49.99 }
  ],
  total: 79.98,
  clearCart: mockClearCart
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCart
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const validShipping = {
  street: '123 Procrastinator Lane',
  city: 'Ankh-Morpork',
  state: 'CA',
  zip: '90210'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Lu-Tze'
};

describe('Checkout', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-001' });
  });

  // Happy path - the path sweeps itself when you do it right
  describe('complete checkout flow', () => {
    it('progresses through all steps to confirmation', async () => {
      const user = userEvent.setup();
      render(<Checkout onComplete={mockOnComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip code/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      expect(screen.getByText(/\$79\.98/)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText(/ORD-001/)).toBeInTheDocument();
      expect(mockOnComplete).toHaveBeenCalledWith('ORD-001');
    });
  });

  describe('shipping validation', () => {
    it('shows error for empty street', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('shows error for invalid ZIP format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'ABC');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('payment validation', () => {
    it('rejects invalid card number', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to payment
      await fillShippingForm(user);

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card/i)).toBeInTheDocument();
    });
  });

  describe('error handling', () => {
    it('displays payment failure and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);

      await completeToReview(user);
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByText(/card declined/i)).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('loading states', () => {
    it('disables buttons during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      const user = userEvent.setup();
      render(<Checkout />);

      await completeToReview(user);
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  describe('edge cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(mockCart).items = [];
      render(<Checkout onCancel={mockOnCancel} />);

      expect(screen.getByText(/cart is empty/i)).toBeInTheDocument();
    });
  });

  describe('accessibility', () => {
    it('has no violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});

// Helpers - sweep the repetition away
async function fillShippingForm(user) {
  await user.type(screen.getByLabelText(/street/i), validShipping.street);
  await user.type(screen.getByLabelText(/city/i), validShipping.city);
  await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
  await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
  await user.click(screen.getByRole('button', { name: /continue/i }));
}
